<?php
session_start();
require_once 'db_connect.php';
if (!isset($_SESSION['user_id'])) { header('Location: login.php'); exit(); }
$me=(int)$_SESSION['user_id']; $role=$_SESSION['role'] ?? '';
if ($role === 'admin') {
  $stmt=$conn->prepare("SELECT id, CONCAT_WS(' ',first_name,middle_name,last_name) AS full_name, role, email FROM users WHERE id<>? AND COALESCE(is_deleted,0)=0 ORDER BY full_name");
} else {
  $stmt=$conn->prepare("SELECT id, CONCAT_WS(' ',first_name,middle_name,last_name) AS full_name, role, email FROM users WHERE role='admin' AND COALESCE(is_deleted,0)=0 ORDER BY full_name");
}
if ($role === 'admin') $stmt->bind_param('i',$me);
$stmt->execute(); $contacts=$stmt->get_result()->fetch_all(MYSQLI_ASSOC); $stmt->close();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Chat - Webyte</title><style>body{margin:0;background:#f3f7f4;font:15px Arial,sans-serif;color:#1e2b20}.wrap{max-width:900px;margin:24px auto;padding:16px}.panel{background:white;border-radius:16px;box-shadow:0 8px 28px #0001;overflow:hidden}.head{padding:18px 22px;background:#108a00;color:white}.controls{padding:16px;display:flex;gap:10px}.controls select,.controls input{padding:10px;border:1px solid #ccd5ce;border-radius:8px;min-width:0}.controls select{flex:1}.messages{height:55vh;overflow:auto;padding:18px;background:#f9fbf9}.msg{padding:10px 13px;margin:8px 0;border-radius:12px;max-width:75%;overflow-wrap:anywhere;background:#e9efea}.mine{background:#d9f4d3;margin-left:auto}.stamp{font-size:11px;color:#657167;margin-top:4px}.send{display:flex;gap:10px;padding:14px;border-top:1px solid #e3e9e4}.send input{flex:1;min-width:0;padding:12px;border:1px solid #ccd5ce;border-radius:8px}.send button,.back{background:#108a00;color:white;border:0;border-radius:8px;padding:11px 15px;cursor:pointer;text-decoration:none}@media(max-width:600px){.wrap{margin:0;padding:8px}.messages{height:60vh}.controls{flex-direction:column}}</style></head><body><div class="wrap"><p><a class="back" href="<?= $role==='admin'?'admin_dashboard.php':($role==='faculty'?'teacher_dashboard.php':'student_dashboard.php') ?>">Back to Dashboard</a></p><section class="panel"><div class="head"><h2 style="margin:0">Webyte Chat</h2><p style="margin:6px 0 0">Send and receive messages</p></div><div class="controls"><label for="contact">Contact</label><select id="contact"><option value="">Select a contact</option><?php foreach($contacts as $c):?><option value="<?=$c['id']?>"><?=htmlspecialchars(trim($c['full_name']).' — '.$c['role'].' ('.$c['email'].')')?></option><?php endforeach;?></select></div><div id="messages" class="messages" aria-live="polite"><p>Select a contact to view messages.</p></div><form id="sendForm" class="send"><input id="message" maxlength="4000" placeholder="Write a message..." autocomplete="off" required><button type="submit">Send</button></form></section></div><script>
const contact=document.getElementById('contact'), box=document.getElementById('messages'), msg=document.getElementById('message');
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
async function loadMessages(){if(!contact.value)return;try{const r=await fetch('get_messages.php?user_id='+encodeURIComponent(contact.value),{cache:'no-store'});const data=await r.json();box.innerHTML=data.length?data.map(m=>`<div class="msg ${m.is_outgoing?'mine':''}">${esc(m.message)}<div class="stamp">${esc(m.created_at_formatted||'')}</div></div>`).join(''):'<p>No messages yet. Start the conversation below.</p>';box.scrollTop=box.scrollHeight;}catch(e){box.innerHTML='<p>Unable to load messages. Please try again.</p>';}}
contact.addEventListener('change',loadMessages);document.getElementById('sendForm').addEventListener('submit',async e=>{e.preventDefault();if(!contact.value){alert('Select a contact first.');return;}const text=msg.value.trim();if(!text)return;const d=new FormData();d.append('user_id',contact.value);d.append('message',text);try{const r=await fetch('send_message.php',{method:'POST',body:d});const out=await r.json();if(out.status==='success'){msg.value='';await loadMessages();}else alert(out.message||'Message could not be sent.');}catch(e){alert('Unable to send the message.');}});setInterval(loadMessages,4000);
</script></body></html>
